import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';
import EditApplicationModal from './EditApplicationModal';

const ArtistApplications = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [applications, setApplications] = useState([]);
  const [selectedApp, setSelectedApp] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingApp, setEditingApp] = useState(null);
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (user?.id) {
      loadApplications();
    } else {
      setLoading(false);
    }
  }, [user?.id, loadApplications]);

  const loadApplications = useCallback(async () => {
    if (!user?.id) {
      console.log('No user ID, skipping load');
      setLoading(false);
      return;
    }

    console.log('Loading applications for user:', user.id);

    try {
      const { data, error } = await supabase
        .from('applications')
        .select(`
          *,
          projects:project_id (
            *,
            architect:architect_id (
              full_name
            )
          )
        `)
        .eq('artist_id', user.id)
        .order('created_at', { ascending: false });

      console.log('Applications query result:', { data, error });

      if (error) throw error;
      setApplications(data || []);
    } catch (error) {
      console.error('Error loading applications:', error);
      setMessage(`Error loading applications: ${error.message}`);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  const handleWithdraw = async (appId) => {
    if (!window.confirm('Are you sure you want to withdraw this application?')) return;

    try {
      const { error } = await supabase
        .from('applications')
        .update({ status: 'withdrawn' })
        .eq('id', appId);

      if (error) throw error;

      setMessage('✅ Application withdrawn successfully');
      await loadApplications();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error withdrawing application:', error);
      setMessage('❌ Error withdrawing application');
    }
  };

  const handleEditApplication = (app) => {
    setEditingApp(app);
    setShowEditModal(true);
  };

  const handleEditSuccess = () => {
    setShowEditModal(false);
    setEditingApp(null);
    setMessage('✅ Application updated successfully!');
    loadApplications();
    setTimeout(() => setMessage(''), 3000);
  };

  const getStatusInfo = (status) => {
    const statuses = {
      pending: {
        label: 'Awaiting Response',
        class: 'status-pending',
        icon: '⏳'
      },
      accepted: {
        label: 'Accepted',
        class: 'status-accepted',
        icon: '✅'
      },
      rejected: {
        label: 'Rejected',
        class: 'status-rejected',
        icon: '❌'
      },
      withdrawn: {
        label: 'Withdrawn',
        class: 'status-expired',
        icon: '↩️'
      }
    };
    return statuses[status] || statuses.pending;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    });
  };

  if (loading) {
    return <div className="loading">Loading applications...</div>;
  }

  if (selectedApp) {
    const statusInfo = getStatusInfo(selectedApp.status);

    return (
      <div>
        <button onClick={() => setSelectedApp(null)} className="btn-back">
          ← Back to Applications
        </button>

        <div className="application-detail-container">
          <div className="application-detail-header">
            <h2 className="section-title">{selectedApp.projects.title}</h2>
            <span className={`status-badge ${statusInfo.class}`}>
              {statusInfo.icon} {statusInfo.label}
            </span>
          </div>

          <div className="application-detail-grid">
            <div className="application-detail-main">
              <div className="detail-section">
                <h3 className="detail-subtitle">Project Description</h3>
                <p className="detail-text">{selectedApp.projects.description}</p>
              </div>

              {selectedApp.projects.reference_images && selectedApp.projects.reference_images.length > 0 && (
                <div className="detail-section">
                  <h3 className="detail-subtitle">Reference Images</h3>
                  <div className="reference-images-grid">
                    {selectedApp.projects.reference_images.map((img, idx) => (
                      <img key={idx} src={img} alt={`Ref ${idx + 1}`} className="reference-image" />
                    ))}
                  </div>
                </div>
              )}

              <div className="detail-section">
                <h3 className="detail-subtitle">Your Proposal</h3>
                <p className="detail-text">{selectedApp.proposal}</p>
              </div>

              {selectedApp.rejection_reason && (
                <div className="detail-section rejection-feedback">
                  <h3 className="detail-subtitle">Client Feedback</h3>
                  <p className="detail-text">{selectedApp.rejection_reason}</p>
                </div>
              )}
            </div>

            <div className="application-detail-sidebar">
              <div className="project-info-card">
                <div className="project-info-item">
                  <span className="project-info-label">Client</span>
                  <span className="project-info-value-medium">
                    {selectedApp.projects.architect.full_name}
                  </span>
                </div>
                <div className="project-info-item">
                  <span className="project-info-label">Your Price</span>
                  <span className="project-info-value-medium">
                    R$ {selectedApp.quoted_price.toFixed(2)}
                  </span>
                </div>
                <div className="project-info-item">
                  <span className="project-info-label">Proposed Timeline</span>
                  <span className="project-info-value-medium">
                    {selectedApp.delivery_timeline} days
                  </span>
                </div>
                <div className="project-info-item">
                  <span className="project-info-label">Application Submitted</span>
                  <span className="project-info-value-small">
                    {formatDate(selectedApp.created_at)}
                  </span>
                </div>
              </div>

              {selectedApp.status === 'pending' && (
                <>
                  <button
                    onClick={() => handleEditApplication(selectedApp)}
                    className="btn-primary btn-full-width"
                  >
                    Edit Application
                  </button>
                  <button
                    onClick={() => handleWithdraw(selectedApp.id)}
                    className="btn-secondary btn-full-width"
                    style={{ marginTop: '10px' }}
                  >
                    Withdraw Application
                  </button>
                </>
              )}

              {selectedApp.status === 'accepted' && (
                <div className="success-message">
                  <p>🎉 Congratulations! Your proposal was accepted.</p>
                  <p>Go to "Projects" to start working.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="artist-applications-container">
      <h2 className="section-title">My Applications</h2>
      <p className="subtitle">Track the status of your proposals</p>

      {message && (
        <div className={`message ${message.includes('✅') ? 'message-success' : 'message-error'}`}>
          {message}
        </div>
      )}

      {applications.length === 0 ? (
        <div className="empty-state">
          <p className="empty-state-title">No applications submitted</p>
          <p className="empty-state-text">
            Explore available projects and submit your proposals!
          </p>
          <Link to="/dashboard/artist/browse-projects" className="btn-primary" style={{ marginTop: '1rem' }}>
            Explore Available Projects
          </Link>
        </div>
      ) : (
        <div className="applications-grid">
          {applications.map(app => {
            const statusInfo = getStatusInfo(app.status);

            return (
              <div
                key={app.id}
                className="application-summary-card"
                onClick={() => setSelectedApp(app)}
              >
                <div className="application-summary-header">
                  <h3 className="application-summary-title">
                    {app.projects.title}
                  </h3>
                  <span className={`status-badge ${statusInfo.class}`}>
                    {statusInfo.icon} {statusInfo.label}
                  </span>
                </div>

                <div className="application-summary-body">
                  <div className="summary-info">
                    <span className="summary-label">Client:</span>
                    <span className="summary-value">
                      {app.projects.architect.full_name}
                    </span>
                  </div>
                  <div className="summary-info">
                    <span className="summary-label">Your Price:</span>
                    <span className="summary-value">
                      R$ {app.quoted_price.toFixed(2)}
                    </span>
                  </div>
                  <div className="summary-info">
                    <span className="summary-label">Submitted on:</span>
                    <span className="summary-value">
                      {formatDate(app.created_at)}
                    </span>
                  </div>
                </div>

                <div className="application-summary-footer">
                  <button className="btn-secondary-small">
                    View Details →
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {showEditModal && editingApp && (
        <EditApplicationModal
          application={editingApp}
          onClose={() => setShowEditModal(false)}
          onSuccess={handleEditSuccess}
        />
      )}
    </div>
  );
};

export default ArtistApplications;